export type OrgFieldType =
  | "text"
  | "textarea"
  | "date"
  | "number"
  | "currency"
  | "percent"
  | "email"
  | "tel"
  | "url"
  | "select"
  | "list"
  | "checkbox"
  | "file"
  | "readonly"
  | "studio-permissions"
  | "assigned-products"
  | "audit-history";

export type OrgFieldOption = { value: string; label: string };

export type OrgFieldBind =
  | "name"
  | "code"
  | "legalName"
  | "status"
  | "type"
  | "notes"
  | "parentCompanyName"
  | "parentCompanyName"
  | "contactName"
  | "contactEmail"
  | "contactPhone"
  | "address"
  | "createdBy"
  | "createdDate"
  | "lastModifiedBy"
  | "lastModifiedDate";

export type OrgField = {
  key: string;
  label: string;
  type: OrgFieldType;
  required?: boolean;
  placeholder?: string;
  help?: string;
  options?: OrgFieldOption[];
  bind?: OrgFieldBind;
  wide?: boolean;
};

export type OrgSection = {
  key: string;
  title: string;
  hint?: string;
  intro?: string;
  fields: OrgField[];
};

export type OrgTypeFieldConfig = {
  sections: OrgSection[];
};

const opt = (value: string, label?: string): OrgFieldOption => ({ value, label: label || value });

