"use client";

import { useState, useTransition } from "react";
import { assignProductAction, removeProductAssignmentAction } from "@/app/actions/organizations";
import type { Organization, Product } from "@/lib/types";
import { Icon } from "./icons";

export function OrgAssignedProductsField({
  organization,
  products,
  returnTo,
}: {
  organization?: Organization;
  products: Product[];
  returnTo: string;
}) {
  const [pending, startTransition] = useTransition();
  const [pendingId, setPendingId] = useState<string | null>(null);
  const [productId, setProductId] = useState(products[0]?.id || "");
  const [role, setRole] = useState("Carrier");
  const [status, setStatus] = useState<"active" | "inactive">("active");
  const [error, setError] = useState("");

  if (!organization) {
    return (
      <div className="org-empty">
        <Icon name="link" size={22} />
        <p>Save the organization first to assign products.</p>
      </div>
    );
  }

  const assignments = organization.assignedProducts || [];
  const org = organization;

  function assign() {
    setError("");
    if (!productId) {
      setError("Select a product to assign.");
      return;
    }
    setPendingId(productId);
    const fd = new FormData();
    fd.set("productId", productId);
    fd.append("organizationIds", org.id);
    fd.set("role", role || "Distributor");
    fd.set("status", status);
    fd.set("returnTo", returnTo);
    startTransition(() => assignProductAction(fd));
  }

  function remove(targetProductId: string, productName: string) {
    if (!window.confirm(`Remove "${productName}" from this organization?`)) return;
    setPendingId(targetProductId);
    const fd = new FormData();
    fd.set("organizationId", org.id);
    fd.set("productId", targetProductId);
    fd.set("returnTo", returnTo);
    startTransition(() => removeProductAssignmentAction(fd));
  }

  return (
    <div className="org-config-assigned">
      {error ? (
        <div className="callout callout-error">
          <Icon name="x" size={14} />
          <div>{error}</div>
        </div>
      ) : null}

      {assignments.length > 0 ? (
        <div className="table-wrap" style={{ marginBottom: "var(--space-4)" }}>
          <table>
            <thead>
              <tr>
                <th>Product</th>
                <th>Code</th>
                <th>Version</th>
                <th>LOB</th>
                <th>Assigned</th>
                <th>Effective</th>
                <th>Status</th>
                <th>Progress</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {assignments.map((assignment) => {
                const product = products.find((p) => p.id === assignment.productId);
                return (
                  <tr key={assignment.productId}>
                    <td className="fw-600">{assignment.productName}</td>
                    <td className="text-mono">{assignment.productId}</td>
                    <td>{product?.version || "—"}</td>
                    <td>{product?.family || "—"}</td>
                    <td>{assignment.since}</td>
                    <td>{product?.effectiveFrom || "—"}</td>
                    <td><span className={`org-status-badge ${assignment.status === "active" ? "on" : "off"}`}>{assignment.status}</span></td>
                    <td>{product?.status === "published" ? "Published" : product?.status === "draft" ? "In progress" : assignment.status === "active" ? "Active" : "—"}</td>
                    <td>
                      <button
                        className="org-icon-btn danger"
                        type="button"
                        title="Remove assignment"
                        disabled={pending && pendingId === assignment.productId}
                        onClick={() => remove(assignment.productId, assignment.productName)}
                      >
                        <Icon name="trash" />
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      ) : (
        <p className="org-config-muted">No products assigned yet. Assign below.</p>
      )}

      <div className="org-assign-row">
        <select
          className="form-control"
          name="assignProductId"
          value={productId}
          onChange={(e) => setProductId(e.target.value)}
        >
          {products.length === 0 ? <option value="">No products available</option> : null}
          {products.map((product) => (
            <option key={product.id} value={product.id}>{product.name} ({product.id})</option>
          ))}
        </select>
        <input
          className="form-control"
          name="assignRole"
          placeholder="Role"
          value={role}
          onChange={(e) => setRole(e.target.value)}
        />
        <select className="form-control" name="assignStatus" value={status} onChange={(e) => setStatus(e.target.value as "active" | "inactive")}>
          <option value="active">Active</option>
          <option value="inactive">Inactive</option>
        </select>
        <button
          className="btn btn-primary"
          type="button"
          disabled={pending}
          onClick={assign}
        >
          {pending ? "Assigning…" : "Assign product"}
        </button>
      </div>
    </div>
  );
}
